import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart'; import 'package:go_router/go_router.dart';
import '../../state/providers.dart'; import '../../widgets/app_scaffold.dart'; import 'widgets/member_avatar.dart'; import 'widgets/tree_edge_painter.dart';
class TreeCanvasScreen extends ConsumerWidget{ const TreeCanvasScreen({super.key,required this.familyId}); final String familyId; @override Widget build(BuildContext context, WidgetRef ref){ final fam=ref.watch(familyProvider(familyId)).valueOrNull; final members=ref.watch(membersProvider(familyId)).valueOrNull??[]; final pos=<String,Offset>{}; for(var i=0;i<members.length;i++){pos[members[i].id]=Offset((i%4)*180+80,(i~/4)*180+80);} return AppScaffold(title:fam?.name??'Tree', familyId:familyId, actions:[IconButton(onPressed:()=>context.go('/family/$familyId/member/new'), icon:const Icon(Icons.person_add))], child: Column(children:[Padding(padding: const EdgeInsets.all(12), child: Autocomplete<String>(optionsBuilder:(t)=>members.map((m)=>'${m.data['firstName']} ${m.data['lastName']}').where((n)=>n.toLowerCase().contains(t.text.toLowerCase())), onSelected:(s){final m=members.firstWhere((m)=>'$s'=='${m.data['firstName']} ${m.data['lastName']}'); context.go('/family/$familyId/member/${m.id}');}, fieldViewBuilder:(c,tc,fn,sub)=>TextField(controller:tc, focusNode:fn, decoration: const InputDecoration(prefixIcon:Icon(Icons.search), hintText:'Search family')))), Expanded(child: GestureDetector(onDoubleTap:()=>context.go('/family/$familyId/member/new'), child: InteractiveViewer(minScale:.3,maxScale:2.5,boundaryMargin: const EdgeInsets.all(500), child:SizedBox(width:900,height:650, child:Stack(children:[CustomPaint(size: const Size(900,650), painter: TreeEdgePainter(members,pos)), for(final m in members) Positioned(left:pos[m.id]!.dx, top:pos[m.id]!.dy, child: InkWell(onTap:()=>context.go('/family/$familyId/member/${m.id}'), child: Column(children:[MemberAvatar(member:m, settings:fam!.settings), Text('${m.data['firstName']}')])))])))))])); }}
